// Microsoft Advertising UET tag (ti XXX) for Shopify, as generated by Microsoft (tm "spfy_ui"),
// plus enhanced conversions: the customer's email/phone are set right before the purchase event.
// Installed in Shopify admin > Settings > Customer events > custom pixel "Microsoft UET".

// Step 1. Initialize the JavaScript pixel SDK (make sure to exclude HTML)
(function(w, d, t, u, o) {
    w[u] = w[u] || [], o.ts = (new Date).getTime();
    var n = d.createElement(t);
    n.src = "https://bat.bing.net/bat.js?ti=" + o.ti + ("uetq" != u ? "&q=" + u : ""),
    n.async = 1, n.onload = n.onreadystatechange = function() {
        var s = this.readyState;
        s && "loaded" !== s && "complete" !== s ||
        (o.q = w[u], w[u] = new UET(o), w[u].push("pageLoad"),
        n.onload = n.onreadystatechange = null)
    };
    var i = d.getElementsByTagName(t)[0];
    i.parentNode.insertBefore(n, i);
    })(window, document, "script", "uetq", {
        ti: "XXX",
        tm: "spfy_ui",
        enableAutoSpaTracking: true
});
window.uetq = window.uetq || [];
window.uetq.push('consent', 'update', {
    'ad_storage': 'granted'
    });

// Step 2. Subscribe to customer events with analytics.subscribe(), and add tracking
analytics.subscribe("page_viewed", (event) => {
  window.uetq = window.uetq || [];
  window.uetq.push('event', 'page_view', { 'page_location': event.context.window.location.href });
});

analytics.subscribe("all_standard_events", event => {

  let productIds = '';
  let revenueValue = 0;
  let currency = '';

  switch (event.name) {
    case "product_viewed":
      if (event.data?.productVariant) {
        productIds = String(event.data.productVariant.product.id);
        window.uetq = window.uetq || [];
        window.uetq.push('event', '', {
          'ecomm_prodid': productIds,
          'ecomm_pagetype': 'product'
        });
      }
      break;

    case "cart_viewed":
      if (event.data?.cart) {
        if (Array.isArray(event.data?.cart?.lines)) {
          const cartItemIds = event.data.cart.lines.map(line => String(line.merchandise.product.id));
          productIds = cartItemIds.join(',').slice(0, 50);
        }
        window.uetq = window.uetq || [];
        window.uetq.push('event', 'product_page', {
          'ecomm_prodid': productIds,
          'ecomm_pagetype': 'cart'
        });
      }
      break;

    case "product_added_to_cart":
      if (event.data?.cartLine) {
        productIds = String(event.data.cartLine.merchandise.product.id);
        window.uetq = window.uetq || [];
        window.uetq.push('event', 'add_to_cart', {
          'ecomm_prodid': productIds,
          'ecomm_pagetype': 'cart'
        });
      }
      break;

    case "checkout_completed":
      if (event.data?.checkout) {
        revenueValue = event.data.checkout.totalPrice?.amount;
        currency = event.data.checkout.totalPrice?.currencyCode;

        if (Array.isArray(event.data?.checkout?.lineItems)) {
          const lineItemIds = event.data.checkout.lineItems.map(item => String(item.variant.product.id));
          productIds = lineItemIds.join(',').slice(0, 50);
        }

        window.uetq = window.uetq || [];
        // Enhanced conversions: the buyer's email and phone from this checkout (empty string if missing).
        const checkout = event.data.checkout;
        const email = (checkout.email || '').trim().toLowerCase();
        const phone = (checkout.phone || checkout.shippingAddress?.phone || '').replace(/[^\d+]/g, '');
        window.uetq.push('set', { 'pid': { 'em': email, 'ph': phone } });
        window.uetq.push('event', 'purchase', {
          'ecomm_prodid': productIds,
          'ecomm_pagetype': 'purchase',
          'revenue_value': revenueValue,
          'currency': currency
        });
      }
      break;
  }
});
